begin;
set local plpgsql.check_asserts=on;
do $$
declare
 v_owner uuid:=gen_random_uuid();v_staff uuid:=gen_random_uuid();v_member uuid:=gen_random_uuid();v_other uuid:=gen_random_uuid();
 v_day date:=(now() at time zone 'America/Santiago')::date+2;v_at timestamptz;v_input jsonb;v_a jsonb;v_b jsonb;v_c jsonb;v_id uuid;v_hash text:=repeat('a',64);v_count bigint;v_config jsonb;
begin
 insert into auth.users(id,email,raw_app_meta_data) values(v_owner,'res-owner-'||v_owner||'@example.invalid','{"role":"superadmin"}'),(v_staff,'res-staff-'||v_staff||'@example.invalid','{"role":"cashier"}'),(v_member,'res-member-'||v_member||'@example.invalid','{}'),(v_other,'res-other-'||v_other||'@example.invalid','{}');
 insert into public.user_roles(user_id,role_id) select v_owner,id from public.roles where name='superadmin';
 insert into public.user_roles(user_id,role_id) select v_staff,id from public.roles where name='cashier';
 v_at:=v_day::timestamp at time zone 'America/Santiago'+interval '13 hours';
 select count(*) into v_count from public.club_coupons;
 assert (public.reservation_config(false)->>'advanceMinutes')::int=120,'anticipación';
 assert not public.reservation_config(false) ? 'tables','config pública no incluye mapa interno';
 assert (select closes from public.reservation_hours where day=0)='18:00','domingo';
 assert (select count(*) from public.reservation_tables)=26,'26 mesas';
 assert (select maximum from public.reservation_tables where number=8)=3 and (select maximum from public.reservation_tables where number=15)=3,'mesas pequeñas';
 v_input:=jsonb_build_object('requestId',gen_random_uuid(),'customerName','Reserva temporal','customerPhone','+56912345678','partySize',6,'reservedAt',v_at,'areaPreference','salon');
 v_a:=public.reservation_create(null,false,v_input,v_hash);v_id:=(v_a->>'id')::uuid;
 assert v_a->>'status'='pending' and v_a->>'durationMinutes'='120','solicitud no confirma, grupo 120 min';
 assert not v_a ? 'access_hash' and not v_a ? 'staffNote','sin secretos ni notas internas';
 assert public.reservation_create(null,false,v_input,v_hash)->>'id'=v_a->>'id','reintento idempotente';
 assert public.reservation_customer_access(v_id,null,v_hash)->>'id'=v_a->>'id','enlace privado';
 begin perform public.reservation_customer_access(v_id,v_other,null);raise exception 'TEST_FAILED: acceso anónimo por usuario cualquiera';exception when raise_exception then if sqlerrm<>'RESERVATION_NOT_FOUND' then raise;end if;end;
 begin perform public.reservation_customer_access(v_id,null,repeat('b',64));raise exception 'TEST_FAILED: token incorrecto';exception when raise_exception then if sqlerrm<>'RESERVATION_NOT_FOUND' then raise;end if;end;
 v_a:=public.reservation_update(v_staff,v_id,'{"status":"confirmed","tableNumbers":[1,2]}');
 assert v_a->>'confirmedCapacity'='6','unión pequeña para seis';
 assert (select actor_id from public.reservation_events where reservation_id=v_id and event='staff_update' limit 1)=v_staff,'responsable auditado';
 v_b:=public.reservation_create(v_member,false,v_input||jsonb_build_object('requestId',gen_random_uuid(),'customerPhone','+56912345679','partySize',2),v_hash);
 begin perform public.reservation_update(v_staff,(v_b->>'id')::uuid,'{"status":"confirmed","tableNumbers":[2]}');raise exception 'TEST_FAILED: superposición';exception when raise_exception then if sqlerrm<>'RESERVATION_OVERLAP' then raise;end if;end;
 assert (public.reservation_customer_access((v_b->>'id')::uuid,v_member,null)->>'status')='pending','fallo no confirma';
 begin perform public.reservation_update(v_other,v_id,'{"status":"cancelled"}');raise exception 'TEST_FAILED: socio modifica agenda';exception when raise_exception then if sqlerrm<>'RESERVATION_FORBIDDEN' then raise;end if;end;
 begin perform public.reservation_update(v_staff,(v_b->>'id')::uuid,'{"status":"confirmed","tableNumbers":[10,9],"confirmedCapacity":4}');raise exception 'TEST_FAILED: filas distintas';exception when raise_exception then if sqlerrm<>'RESERVATION_PAIR_INVALID' then raise;end if;end;
 begin perform public.reservation_update(v_staff,(v_b->>'id')::uuid,'{"status":"confirmed","tableNumbers":[10,12]}');raise exception 'TEST_FAILED: capacidad sin revisar';exception when raise_exception then if sqlerrm<>'RESERVATION_CAPACITY_REVIEW' then raise;end if;end;
 v_b:=public.reservation_update(v_staff,(v_b->>'id')::uuid,'{"status":"confirmed","tableNumbers":[10,12],"confirmedCapacity":4,"staffNote":"Se comprobó comodidad"}');
 assert v_b->>'status'='confirmed','capacidad comprobada';
 assert (public.reservation_list(v_other,false)->>'total')::int=0,'otro socio no ve reservas';
 assert (public.reservation_list(v_member,false)->>'total')::int=1,'solo reservas propias';
 begin perform public.reservation_update(v_staff,v_id,'{"status":"no_show"}');raise exception 'TEST_FAILED: ausencia anticipada';exception when raise_exception then if sqlerrm<>'RESERVATION_TOLERANCE' then raise;end if;end;
 begin perform public.reservation_create(null,false,v_input||jsonb_build_object('requestId',gen_random_uuid(),'customerPhone','+56912345670','reservedAt',v_day::timestamp at time zone 'America/Santiago'+interval '18 hours'),v_hash);raise exception 'TEST_FAILED: visita sobre cierre';exception when raise_exception then if sqlerrm<>'RESERVATION_HOURS' then raise;end if;end;
 begin perform public.reservation_create(null,false,v_input||jsonb_build_object('requestId',gen_random_uuid(),'customerPhone','+56912345670','reservedAt',now()+interval '30 minutes'),v_hash);raise exception 'TEST_FAILED: sin anticipación';exception when raise_exception then if sqlerrm not in ('RESERVATION_ADVANCE','RESERVATION_HOURS') then raise;end if;end;
 v_a:=public.reservation_customer_access(v_id,null,v_hash,true);
 assert v_a->>'status'='cancelled','cancelación propia';
 assert public.reservation_customer_access(v_id,null,v_hash,true)->>'status'='cancelled','cancelación idempotente';
 v_c:=public.reservation_create(null,false,v_input||jsonb_build_object('requestId',gen_random_uuid(),'customerPhone','+56912345670','partySize',3),v_hash);
 perform public.reservation_update(v_staff,(v_c->>'id')::uuid,'{"status":"confirmed","tableNumbers":[2]}');
 begin perform public.reservation_update(v_staff,(v_c->>'id')::uuid,'{"status":"confirmed","tableNumbers":[9,11,13],"confirmedCapacity":12}');raise exception 'TEST_FAILED: cashier grupo especial';exception when raise_exception then if sqlerrm<>'RESERVATION_SPECIAL_GROUP' then raise;end if;end;
 perform public.reservation_update(v_owner,(v_c->>'id')::uuid,'{"status":"confirmed","tableNumbers":[9,11,13],"confirmedCapacity":10}');
 update public.reservation_pairs set enabled=false where a=1 and b=2;
 begin perform public.reservation_update(v_staff,(v_b->>'id')::uuid,'{"status":"confirmed","tableNumbers":[1,2]}');raise exception 'TEST_FAILED: union desactivada';exception when raise_exception then if sqlerrm<>'RESERVATION_PAIR_INVALID' then raise;end if;end;
 v_config:=public.reservation_config(true);
 begin perform public.reservation_save_config(v_staff,v_config);raise exception 'TEST_FAILED: cashier configura';exception when raise_exception then if sqlerrm<>'RESERVATION_FORBIDDEN' then raise;end if;end;
 perform public.reservation_save_config(v_owner,v_config);
 assert (select count(*) from public.club_coupons)=v_count,'no crea descuentos ni modifica cupones';
 assert not has_function_privilege('authenticated','public.reservation_update(uuid,uuid,jsonb)','EXECUTE'),'RPC cerrada al cliente';
 assert not has_table_privilege('anon','public.reservations','SELECT'),'sin datos públicos';
end;$$;
select 'OK: privacidad, roles, idempotencia, mesas, uniones, capacidad, superposición, horarios, cancelación y auditoría' as result;
rollback;
